import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int len = s.length();
        int max = (int)Math.pow(10, len);
        int count = 0;

        for (int num = 0; num < max; num += 25) {
            if (isValid(s, num)) {
                count++;
            }
        }
        System.out.println(count);
    }

    private static boolean isValid(String pattern, int number) {
        String numStr = String.format("%0" + pattern.length() + "d", number);
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            char d = numStr.charAt(i);
            if (p == 'X') continue;
            if (p == '_') continue;
            if (p != d) return false;
        }
        return true;
    }
}
